import React, { useEffect, useState } from "react";
import "./index.scss";

const SECTION_IDS = ["about", "portfolio", "contact"];
const NAV_OFFSET = 80; // height of your fixed nav

const ScrollArrow = () => {
  const [isAtEnd, setIsAtEnd] = useState(false);

  const getSections = () => {
    return SECTION_IDS.map((id) => {
      const el = document.getElementById(id);
      if (!el) return null;
      return {
        id,
        el,
        top: el.offsetTop,
      };
    }).filter(Boolean);
  };

  // Flip arrow when we reach the last section
  useEffect(() => {
    const handleScroll = () => {
      const sections = getSections();
      if (!sections.length) return;

      const last = sections[sections.length - 1];
      const scrollY = window.scrollY || window.pageYOffset;

      // when we've scrolled to / past the last section, arrow points up
      if (scrollY + NAV_OFFSET >= last.top - 16) {
        setIsAtEnd(true);
      } else {
        setIsAtEnd(false);
      }
    };

    handleScroll();
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const handleClick = () => {
    const sections = getSections();
    if (!sections.length) return;

    const scrollY = window.scrollY || window.pageYOffset;

    // If we're at the end, go back to the top
    if (isAtEnd) {
      window.scrollTo({
        top: 0,
        behavior: "smooth",
      });
      return;
    }

    // Otherwise, go to the next section in order
    for (let i = 0; i < sections.length; i += 1) {
      const { top } = sections[i];
      // find the first section whose top is below our current scroll
      if (scrollY + NAV_OFFSET + 5 < top) {
        window.scrollTo({
          top: top - NAV_OFFSET,
          behavior: "smooth",
        });
        return;
      }
    }

    // Fallback: if somehow none matched, scroll to last
    const last = sections[sections.length - 1];
    window.scrollTo({
      top: last.top - NAV_OFFSET,
      behavior: "smooth",
    });
  };

  return (
    <button
      type="button"
      className={`scroll-arrow ${isAtEnd ? "scroll-arrow--up" : "scroll-arrow--down"}`}
      onClick={handleClick}
      aria-label={isAtEnd ? "Scroll to top" : "Scroll to next section"}
    >
      <span className="scroll-arrow-icon" />
    </button>
  );
};

export default ScrollArrow;
